-- =============================================================================
-- Rentrix v1 baseline schema (SYSTEM_DESIGN.md §5, D-09 … D-15)
--
-- Portable across SQLite, MySQL 8 and PostgreSQL 15+ (D-10):
--   * no AUTO_INCREMENT / IDENTITY / SERIAL: internal BIGINT ids are generated by
--     the API (time-ordered 64-bit, D-80), so the DDL is the same everywhere;
--   * no ENGINE, no vendor JSON, no native enums (enums are VARCHAR);
--   * CHECK constraints only for invariants (ranges, landlord <> tenant), never
--     for enum value lists, because SQLite cannot alter a CHECK in place.
--
-- ${timestamp_type} is the one vendor difference: DATETIME(6) on MySQL (its
-- TIMESTAMP type ends in 2038 and shifts with the session time zone) and
-- TIMESTAMP elsewhere. The API sets it at startup (MigrationPlaceholders).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Reference data: cities (D-20)
-- -----------------------------------------------------------------------------
CREATE TABLE cities (
    code            VARCHAR(8)        NOT NULL,
    name            VARCHAR(80)       NOT NULL,
    aliases         VARCHAR(255),
    state           VARCHAR(80)       NOT NULL,
    live            BOOLEAN           NOT NULL DEFAULT FALSE,
    created_at      ${timestamp_type} NOT NULL,
    updated_at      ${timestamp_type} NOT NULL,
    CONSTRAINT pk_cities PRIMARY KEY (code)
);

INSERT INTO cities (code, name, aliases, state, live, created_at, updated_at)
VALUES ('BLR', 'Bangalore', 'Bengaluru', 'Karnataka', TRUE, '2026-11-21 00:00:00.000', '2026-11-21 00:00:00.000');
INSERT INTO cities (code, name, aliases, state, live, created_at, updated_at)
VALUES ('PNQ', 'Pune', NULL, 'Maharashtra', TRUE, '2026-11-21 00:00:00.000', '2026-11-21 00:00:00.000');

-- -----------------------------------------------------------------------------
-- Users and roles (§4, §5.1)
-- -----------------------------------------------------------------------------
CREATE TABLE users (
    id                  BIGINT            NOT NULL,
    public_id           CHAR(36)          NOT NULL,
    google_sub          VARCHAR(255),
    email               VARCHAR(320),
    email_verified_at   ${timestamp_type},
    google_name         VARCHAR(255),
    display_name        VARCHAR(60)       NOT NULL,
    avatar_url          VARCHAR(1024),
    phone               VARCHAR(20),
    onboarded_at        ${timestamp_type},
    last_login_at       ${timestamp_type},
    home_city_code      VARCHAR(8),
    status              VARCHAR(16)       NOT NULL,
    is_demo             BOOLEAN           NOT NULL DEFAULT FALSE,
    deleted_at          ${timestamp_type},
    created_at          ${timestamp_type} NOT NULL,
    updated_at          ${timestamp_type} NOT NULL,
    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT uq_users_public_id UNIQUE (public_id),
    -- NULLs never collide in a UNIQUE constraint on any of the three databases,
    -- so seed users (no google_sub) and deleted users (no email) are allowed.
    CONSTRAINT uq_users_google_sub UNIQUE (google_sub),
    CONSTRAINT uq_users_email UNIQUE (email),
    CONSTRAINT fk_users_home_city FOREIGN KEY (home_city_code) REFERENCES cities (code)
);

CREATE TABLE user_roles (
    user_id     BIGINT      NOT NULL,
    role        VARCHAR(16) NOT NULL,
    CONSTRAINT pk_user_roles PRIMARY KEY (user_id, role),
    CONSTRAINT fk_user_roles_user FOREIGN KEY (user_id) REFERENCES users (id)
);

-- -----------------------------------------------------------------------------
-- Properties (§5.3) and their images (§15)
-- -----------------------------------------------------------------------------
CREATE TABLE properties (
    id              BIGINT            NOT NULL,
    public_id       CHAR(36)          NOT NULL,
    landlord_id     BIGINT            NOT NULL,
    city_code       VARCHAR(8)        NOT NULL,
    locality        VARCHAR(120)      NOT NULL,
    -- lower-cased, trimmed, single-spaced copy of locality, used by search
    locality_key    VARCHAR(120)      NOT NULL,
    building_name   VARCHAR(160),
    street          VARCHAR(200),
    unit_label      VARCHAR(40),
    pincode         CHAR(6)           NOT NULL,
    property_type   VARCHAR(24)       NOT NULL,
    bedrooms        INTEGER,
    bathrooms       INTEGER,
    area_sqft       INTEGER,
    furnishing      VARCHAR(16),
    parking         BOOLEAN,
    description     VARCHAR(2000),
    status          VARCHAR(16)       NOT NULL,
    is_demo         BOOLEAN           NOT NULL DEFAULT FALSE,
    deleted_at      ${timestamp_type},
    created_at      ${timestamp_type} NOT NULL,
    updated_at      ${timestamp_type} NOT NULL,
    CONSTRAINT pk_properties PRIMARY KEY (id),
    CONSTRAINT uq_properties_public_id UNIQUE (public_id),
    CONSTRAINT fk_properties_landlord FOREIGN KEY (landlord_id) REFERENCES users (id),
    CONSTRAINT fk_properties_city FOREIGN KEY (city_code) REFERENCES cities (code),
    CONSTRAINT ck_properties_facts CHECK (
        (bedrooms IS NULL OR bedrooms >= 0)
        AND (bathrooms IS NULL OR bathrooms >= 0)
        AND (area_sqft IS NULL OR area_sqft > 0))
);
-- Search: GET /properties?city=&locality= lists PUBLISHED rows of one city.
CREATE INDEX ix_properties_city_status_locality ON properties (city_code, status, locality_key);
CREATE INDEX ix_properties_landlord ON properties (landlord_id, status);

CREATE TABLE property_images (
    id              BIGINT            NOT NULL,
    public_id       CHAR(36)          NOT NULL,
    property_id     BIGINT            NOT NULL,
    storage_key     VARCHAR(255)      NOT NULL,
    thumb_key       VARCHAR(255)      NOT NULL,
    content_type    VARCHAR(64)       NOT NULL,
    width           INTEGER           NOT NULL,
    height          INTEGER           NOT NULL,
    size_bytes      BIGINT            NOT NULL,
    display_order   INTEGER           NOT NULL,
    is_primary      BOOLEAN           NOT NULL DEFAULT FALSE,
    created_at      ${timestamp_type} NOT NULL,
    updated_at      ${timestamp_type} NOT NULL,
    CONSTRAINT pk_property_images PRIMARY KEY (id),
    CONSTRAINT uq_property_images_public_id UNIQUE (public_id),
    CONSTRAINT fk_property_images_property FOREIGN KEY (property_id) REFERENCES properties (id)
);
CREATE INDEX ix_property_images_property ON property_images (property_id, display_order);

-- -----------------------------------------------------------------------------
-- Tenancies (§5.4, §6) and rent records (§5.5)
-- -----------------------------------------------------------------------------
CREATE TABLE tenancies (
    id                      BIGINT            NOT NULL,
    public_id               CHAR(36)          NOT NULL,
    property_id             BIGINT            NOT NULL,
    landlord_id             BIGINT            NOT NULL,
    -- null while a landlord-initiated invite waits for a tenant without an account
    tenant_id               BIGINT,
    start_date              DATE              NOT NULL,
    end_date                DATE,
    initial_rent_inr        BIGINT            NOT NULL,
    deposit_inr             BIGINT,
    deposit_refunded_inr    BIGINT,
    status                  VARCHAR(24)       NOT NULL,
    initiated_by            VARCHAR(16)       NOT NULL,
    invite_email            VARCHAR(320),
    decline_reason          VARCHAR(500),
    evidence_level          VARCHAR(16),
    confirmed_at            ${timestamp_type},
    ended_at                ${timestamp_type},
    voided_at               ${timestamp_type},
    void_reason             VARCHAR(500),
    created_at              ${timestamp_type} NOT NULL,
    updated_at              ${timestamp_type} NOT NULL,
    CONSTRAINT pk_tenancies PRIMARY KEY (id),
    CONSTRAINT uq_tenancies_public_id UNIQUE (public_id),
    CONSTRAINT fk_tenancies_property FOREIGN KEY (property_id) REFERENCES properties (id),
    CONSTRAINT fk_tenancies_landlord FOREIGN KEY (landlord_id) REFERENCES users (id),
    CONSTRAINT fk_tenancies_tenant FOREIGN KEY (tenant_id) REFERENCES users (id),
    CONSTRAINT ck_tenancies_parties CHECK (tenant_id IS NULL OR tenant_id <> landlord_id),
    CONSTRAINT ck_tenancies_dates CHECK (end_date IS NULL OR end_date >= start_date),
    CONSTRAINT ck_tenancies_money CHECK (
        initial_rent_inr > 0
        AND (deposit_inr IS NULL OR deposit_inr >= 0)
        AND (deposit_refunded_inr IS NULL OR deposit_refunded_inr >= 0))
);
CREATE INDEX ix_tenancies_property_status ON tenancies (property_id, status);
CREATE INDEX ix_tenancies_tenant_status ON tenancies (tenant_id, status);
CREATE INDEX ix_tenancies_landlord_status ON tenancies (landlord_id, status);
-- Repeat-pair rule (D-44) and the overlap guard (D-23) look up a pair's tenancies.
CREATE INDEX ix_tenancies_pair ON tenancies (landlord_id, tenant_id, start_date);

CREATE TABLE rent_records (
    id                  BIGINT            NOT NULL,
    public_id           CHAR(36)          NOT NULL,
    tenancy_id          BIGINT            NOT NULL,
    effective_from      DATE              NOT NULL,
    monthly_rent_inr    BIGINT            NOT NULL,
    maintenance_inr     BIGINT,
    added_by            BIGINT            NOT NULL,
    status              VARCHAR(16)       NOT NULL,
    created_at          ${timestamp_type} NOT NULL,
    updated_at          ${timestamp_type} NOT NULL,
    CONSTRAINT pk_rent_records PRIMARY KEY (id),
    CONSTRAINT uq_rent_records_public_id UNIQUE (public_id),
    CONSTRAINT fk_rent_records_tenancy FOREIGN KEY (tenancy_id) REFERENCES tenancies (id),
    CONSTRAINT fk_rent_records_added_by FOREIGN KEY (added_by) REFERENCES users (id),
    CONSTRAINT ck_rent_records_money CHECK (
        monthly_rent_inr > 0 AND (maintenance_inr IS NULL OR maintenance_inr >= 0))
);
CREATE INDEX ix_rent_records_tenancy ON rent_records (tenancy_id, effective_from);

CREATE TABLE invite_tokens (
    id              BIGINT            NOT NULL,
    tenancy_id      BIGINT            NOT NULL,
    token_hash      CHAR(64)          NOT NULL,
    email           VARCHAR(320)      NOT NULL,
    expires_at      ${timestamp_type} NOT NULL,
    used_at         ${timestamp_type},
    created_at      ${timestamp_type} NOT NULL,
    updated_at      ${timestamp_type} NOT NULL,
    CONSTRAINT pk_invite_tokens PRIMARY KEY (id),
    CONSTRAINT uq_invite_tokens_hash UNIQUE (token_hash),
    CONSTRAINT fk_invite_tokens_tenancy FOREIGN KEY (tenancy_id) REFERENCES tenancies (id)
);
CREATE INDEX ix_invite_tokens_tenancy ON invite_tokens (tenancy_id);

CREATE TABLE tenancy_documents (
    id              BIGINT            NOT NULL,
    public_id       CHAR(36)          NOT NULL,
    tenancy_id      BIGINT            NOT NULL,
    uploaded_by     BIGINT            NOT NULL,
    storage_key     VARCHAR(255)      NOT NULL,
    content_type    VARCHAR(64)       NOT NULL,
    size_bytes      BIGINT            NOT NULL,
    sha256          CHAR(64)          NOT NULL,
    status          VARCHAR(16)       NOT NULL,
    reviewed_by     BIGINT,
    reviewed_at     ${timestamp_type},
    created_at      ${timestamp_type} NOT NULL,
    updated_at      ${timestamp_type} NOT NULL,
    CONSTRAINT pk_tenancy_documents PRIMARY KEY (id),
    CONSTRAINT uq_tenancy_documents_public_id UNIQUE (public_id),
    CONSTRAINT fk_tenancy_documents_tenancy FOREIGN KEY (tenancy_id) REFERENCES tenancies (id),
    CONSTRAINT fk_tenancy_documents_uploader FOREIGN KEY (uploaded_by) REFERENCES users (id),
    CONSTRAINT fk_tenancy_documents_reviewer FOREIGN KEY (reviewed_by) REFERENCES users (id)
);
CREATE INDEX ix_tenancy_documents_tenancy ON tenancy_documents (tenancy_id);
CREATE INDEX ix_tenancy_documents_status ON tenancy_documents (status, created_at);

-- -----------------------------------------------------------------------------
-- Reviews (§5.6, §7), responses and revisions (§5.7)
-- -----------------------------------------------------------------------------
CREATE TABLE reviews (
    id                      BIGINT            NOT NULL,
    public_id               CHAR(36)          NOT NULL,
    tenancy_id              BIGINT            NOT NULL,
    direction               VARCHAR(24)       NOT NULL,
    author_id               BIGINT            NOT NULL,
    -- landlord or tenant for person directions; null for TENANT_TO_PROPERTY
    subject_user_id         BIGINT,
    property_id             BIGINT            NOT NULL,
    rating_overall          INTEGER           NOT NULL,
    rating_a                INTEGER,
    rating_b                INTEGER,
    rating_c                INTEGER,
    body                    VARCHAR(2000)     NOT NULL,
    status                  VARCHAR(24)       NOT NULL,
    submitted_at            ${timestamp_type} NOT NULL,
    published_at            ${timestamp_type},
    edit_until              ${timestamp_type},
    last_edited_at          ${timestamp_type},
    -- D-40: a review written during an ACTIVE tenancy may be updated once after it ends
    post_end_update_used    BOOLEAN           NOT NULL DEFAULT FALSE,
    hidden_at               ${timestamp_type},
    hidden_reason           VARCHAR(500),
    -- D-50: a PERSONAL_DATA report from a party hides only the text
    text_hidden_at          ${timestamp_type},
    counts_in_aggregate     BOOLEAN           NOT NULL DEFAULT TRUE,
    deleted_at              ${timestamp_type},
    created_at              ${timestamp_type} NOT NULL,
    updated_at              ${timestamp_type} NOT NULL,
    CONSTRAINT pk_reviews PRIMARY KEY (id),
    CONSTRAINT uq_reviews_public_id UNIQUE (public_id),
    -- D-38: one review per direction per tenancy
    CONSTRAINT uq_reviews_tenancy_direction UNIQUE (tenancy_id, direction),
    CONSTRAINT fk_reviews_tenancy FOREIGN KEY (tenancy_id) REFERENCES tenancies (id),
    CONSTRAINT fk_reviews_author FOREIGN KEY (author_id) REFERENCES users (id),
    CONSTRAINT fk_reviews_subject_user FOREIGN KEY (subject_user_id) REFERENCES users (id),
    CONSTRAINT fk_reviews_property FOREIGN KEY (property_id) REFERENCES properties (id),
    -- D-27: integer 1–5 stars, sub-ratings optional
    CONSTRAINT ck_reviews_ratings CHECK (
        rating_overall BETWEEN 1 AND 5
        AND (rating_a IS NULL OR rating_a BETWEEN 1 AND 5)
        AND (rating_b IS NULL OR rating_b BETWEEN 1 AND 5)
        AND (rating_c IS NULL OR rating_c BETWEEN 1 AND 5))
);
-- Rating lookups: reviews about a person (as landlord or as tenant) and about a property.
CREATE INDEX ix_reviews_subject_user ON reviews (subject_user_id, direction, status, published_at);
CREATE INDEX ix_reviews_property ON reviews (property_id, direction, status, published_at);
CREATE INDEX ix_reviews_author ON reviews (author_id, submitted_at);
-- Reveal job (D-46): AWAITING_REVEAL rows ordered by submission time.
CREATE INDEX ix_reviews_status_submitted ON reviews (status, submitted_at);

CREATE TABLE review_responses (
    id              BIGINT            NOT NULL,
    public_id       CHAR(36)          NOT NULL,
    review_id       BIGINT            NOT NULL,
    author_id       BIGINT            NOT NULL,
    body            VARCHAR(1000)     NOT NULL,
    status          VARCHAR(16)       NOT NULL,
    edit_until      ${timestamp_type},
    hidden_at       ${timestamp_type},
    hidden_reason   VARCHAR(500),
    created_at      ${timestamp_type} NOT NULL,
    updated_at      ${timestamp_type} NOT NULL,
    CONSTRAINT pk_review_responses PRIMARY KEY (id),
    CONSTRAINT uq_review_responses_public_id UNIQUE (public_id),
    CONSTRAINT uq_review_responses_review UNIQUE (review_id),
    CONSTRAINT fk_review_responses_review FOREIGN KEY (review_id) REFERENCES reviews (id),
    CONSTRAINT fk_review_responses_author FOREIGN KEY (author_id) REFERENCES users (id)
);

CREATE TABLE review_revisions (
    id              BIGINT            NOT NULL,
    review_id       BIGINT            NOT NULL,
    revision_no     INTEGER           NOT NULL,
    rating_overall  INTEGER           NOT NULL,
    rating_a        INTEGER,
    rating_b        INTEGER,
    rating_c        INTEGER,
    body            VARCHAR(2000)     NOT NULL,
    created_at      ${timestamp_type} NOT NULL,
    updated_at      ${timestamp_type} NOT NULL,
    CONSTRAINT pk_review_revisions PRIMARY KEY (id),
    CONSTRAINT uq_review_revisions_no UNIQUE (review_id, revision_no),
    CONSTRAINT fk_review_revisions_review FOREIGN KEY (review_id) REFERENCES reviews (id)
);

-- -----------------------------------------------------------------------------
-- Enquiries (§5.9) and tenant share links (D-54)
-- -----------------------------------------------------------------------------
CREATE TABLE enquiries (
    id              BIGINT            NOT NULL,
    public_id       CHAR(36)          NOT NULL,
    tenant_id       BIGINT            NOT NULL,
    property_id     BIGINT            NOT NULL,
    message         VARCHAR(1000)     NOT NULL,
    share_contact   BOOLEAN           NOT NULL DEFAULT FALSE,
    status          VARCHAR(16)       NOT NULL,
    expires_at      ${timestamp_type} NOT NULL,
    created_at      ${timestamp_type} NOT NULL,
    updated_at      ${timestamp_type} NOT NULL,
    CONSTRAINT pk_enquiries PRIMARY KEY (id),
    CONSTRAINT uq_enquiries_public_id UNIQUE (public_id),
    CONSTRAINT fk_enquiries_tenant FOREIGN KEY (tenant_id) REFERENCES users (id),
    CONSTRAINT fk_enquiries_property FOREIGN KEY (property_id) REFERENCES properties (id)
);
-- D-32 limits (open count, 7-day volume) and the D-54 landlord access grant.
CREATE INDEX ix_enquiries_tenant_created ON enquiries (tenant_id, created_at);
CREATE INDEX ix_enquiries_property_status ON enquiries (property_id, status, expires_at);

CREATE TABLE share_links (
    id              BIGINT            NOT NULL,
    public_id       CHAR(36)          NOT NULL,
    user_id         BIGINT            NOT NULL,
    token_hash      CHAR(64)          NOT NULL,
    expires_at      ${timestamp_type} NOT NULL,
    revoked_at      ${timestamp_type},
    created_at      ${timestamp_type} NOT NULL,
    updated_at      ${timestamp_type} NOT NULL,
    CONSTRAINT pk_share_links PRIMARY KEY (id),
    CONSTRAINT uq_share_links_public_id UNIQUE (public_id),
    CONSTRAINT uq_share_links_hash UNIQUE (token_hash),
    CONSTRAINT fk_share_links_user FOREIGN KEY (user_id) REFERENCES users (id)
);
CREATE INDEX ix_share_links_user ON share_links (user_id);

-- -----------------------------------------------------------------------------
-- Stored rating aggregates (§5.10, §9)
-- subject_id is users.id (LANDLORD / TENANT) or properties.id (PROPERTY).
-- -----------------------------------------------------------------------------
CREATE TABLE rating_aggregates (
    subject_type    VARCHAR(16)       NOT NULL,
    subject_id      BIGINT            NOT NULL,
    review_count    INTEGER           NOT NULL DEFAULT 0,
    rating_sum      INTEGER           NOT NULL DEFAULT 0,
    average         NUMERIC(3, 2),
    bayes_score     NUMERIC(4, 3),
    count_1         INTEGER           NOT NULL DEFAULT 0,
    count_2         INTEGER           NOT NULL DEFAULT 0,
    count_3         INTEGER           NOT NULL DEFAULT 0,
    count_4         INTEGER           NOT NULL DEFAULT 0,
    count_5         INTEGER           NOT NULL DEFAULT 0,
    sub_a_avg       NUMERIC(3, 2),
    sub_b_avg       NUMERIC(3, 2),
    sub_c_avg       NUMERIC(3, 2),
    last_review_at  ${timestamp_type},
    created_at      ${timestamp_type} NOT NULL,
    updated_at      ${timestamp_type} NOT NULL,
    CONSTRAINT pk_rating_aggregates PRIMARY KEY (subject_type, subject_id)
);
-- "Top rated" sort (D-53): bayes_score, then count, then recency.
CREATE INDEX ix_rating_aggregates_rank ON rating_aggregates (subject_type, bayes_score, review_count, last_review_at);

-- -----------------------------------------------------------------------------
-- Reports and moderation audit log (§5.11, §8)
-- target_id is the internal id of the reported row (polymorphic, no FK).
-- -----------------------------------------------------------------------------
CREATE TABLE reports (
    id              BIGINT            NOT NULL,
    public_id       CHAR(36)          NOT NULL,
    reporter_id     BIGINT            NOT NULL,
    target_type     VARCHAR(24)       NOT NULL,
    target_id       BIGINT            NOT NULL,
    reason          VARCHAR(32)       NOT NULL,
    details         VARCHAR(1000),
    status          VARCHAR(16)       NOT NULL,
    handled_by      BIGINT,
    resolution_note VARCHAR(1000),
    handled_at      ${timestamp_type},
    created_at      ${timestamp_type} NOT NULL,
    updated_at      ${timestamp_type} NOT NULL,
    CONSTRAINT pk_reports PRIMARY KEY (id),
    CONSTRAINT uq_reports_public_id UNIQUE (public_id),
    -- D-49: one report per reporter per target
    CONSTRAINT uq_reports_reporter_target UNIQUE (reporter_id, target_type, target_id),
    CONSTRAINT fk_reports_reporter FOREIGN KEY (reporter_id) REFERENCES users (id),
    CONSTRAINT fk_reports_handled_by FOREIGN KEY (handled_by) REFERENCES users (id)
);
CREATE INDEX ix_reports_status_created ON reports (status, created_at);
CREATE INDEX ix_reports_target ON reports (target_type, target_id);

CREATE TABLE moderation_actions (
    id              BIGINT            NOT NULL,
    admin_id        BIGINT            NOT NULL,
    action          VARCHAR(32)       NOT NULL,
    target_type     VARCHAR(24)       NOT NULL,
    target_id       BIGINT            NOT NULL,
    report_id       BIGINT,
    reason          VARCHAR(1000),
    created_at      ${timestamp_type} NOT NULL,
    updated_at      ${timestamp_type} NOT NULL,
    CONSTRAINT pk_moderation_actions PRIMARY KEY (id),
    CONSTRAINT fk_moderation_actions_admin FOREIGN KEY (admin_id) REFERENCES users (id),
    CONSTRAINT fk_moderation_actions_report FOREIGN KEY (report_id) REFERENCES reports (id)
);
CREATE INDEX ix_moderation_actions_target ON moderation_actions (target_type, target_id, created_at);

-- -----------------------------------------------------------------------------
-- Auth support (D-63) and scheduled-job lock (D-08)
-- -----------------------------------------------------------------------------
CREATE TABLE refresh_tokens (
    id              BIGINT            NOT NULL,
    user_id         BIGINT            NOT NULL,
    token_hash      CHAR(64)          NOT NULL,
    family_id       CHAR(36)          NOT NULL,
    expires_at      ${timestamp_type} NOT NULL,
    revoked_at      ${timestamp_type},
    created_at      ${timestamp_type} NOT NULL,
    updated_at      ${timestamp_type} NOT NULL,
    CONSTRAINT pk_refresh_tokens PRIMARY KEY (id),
    CONSTRAINT uq_refresh_tokens_hash UNIQUE (token_hash),
    CONSTRAINT fk_refresh_tokens_user FOREIGN KEY (user_id) REFERENCES users (id)
);
CREATE INDEX ix_refresh_tokens_user ON refresh_tokens (user_id);
CREATE INDEX ix_refresh_tokens_family ON refresh_tokens (family_id);

-- ShedLock-style lock row per job name; one row is held by one instance at a time.
CREATE TABLE scheduled_job_lock (
    name            VARCHAR(64)       NOT NULL,
    lock_until      ${timestamp_type} NOT NULL,
    locked_at       ${timestamp_type} NOT NULL,
    locked_by       VARCHAR(255)      NOT NULL,
    CONSTRAINT pk_scheduled_job_lock PRIMARY KEY (name)
);
